          "id": "code-ml-28-1-ch28_1_diag",
          "title": "Production Audit: Pergeseran Prevalensi pada AP, Bias +0.3750 Trapezoidal PR-AUC & Dummy MCC",
          "language": "python",
          "filename": "28_1_prevalence_shift_trapz_bias_audit.py",
          "code": "import numpy as np\nfrom sklearn.metrics import (\n    accuracy_score,\n    auc,\n    average_precision_score,\n    f1_score,\n    matthews_corrcoef,\n    precision_recall_curve,\n    roc_auc_score,\n)\n\nrng = np.random.default_rng(2813)\n\n# -----------------------------------------------------------------------------\n# Audit 1: Bahaya Membandingkan PR-AUC Mentah Antar Periode Saat Prevalensi Berubah!\n# Distribusi skor bersyarat P(S|Y=1) & P(S|Y=0) 100% IDENTIK, hanya prevalensi pi yang berubah!\n# -----------------------------------------------------------------------------\nprint(\"=== 1. Audit Sensitivitas Prevalensi (Kualitas Diskriminasi Model 100% Identik!) ===\")\nN_tot = 20_000\nfor pi in [0.002, 0.010, 0.050]:\n    n_pos = int(N_tot * pi)\n    n_neg = N_tot - n_pos\n    y = np.concatenate([np.ones(n_pos, dtype=int), np.zeros(n_neg, dtype=int)])\n    s = np.concatenate([\n        rng.normal(loc=2.0, scale=1.0, size=n_pos),\n        rng.normal(loc=0.0, scale=1.0, size=n_neg),\n    ])\n    roc = roc_auc_score(y, s)\n    ap = average_precision_score(y, s)\n    lift_ap = ap / pi\n    print(f\"Prevalensi pi={pi:5.2%} | ROC-AUC={roc:.4f} (STABIL) | AP={ap:.4f} (BERUBAH {lift_ap:4.1f}x baseline!)\")\n\n# -----------------------------------------------------------------------------\n# Audit 2: Bias Optimis Trapezoidal auc(recall, precision) vs Step AP pada Skor Terkuantisasi (Ties)\n# -----------------------------------------------------------------------------\n# Skor biner / terkuantisasi (misal prediksi keras 0/1 atau pohon dangkal 2 daun):\n# 20 positif tertangkap di skor 1.0 bersama 180 negatif (Prec=10%, Rec=100% jika seluruh 20 tertangkap,\n# atau 16 dari 20 positif -> Rec=80%, Prec=16/196=8.16%, sisanya di skor 0.0).\ny_ties = np.concatenate([np.ones(20, dtype=int), np.zeros(1980, dtype=int)])\ns_ties = np.zeros(2000, dtype=float)\ns_ties[:16] = 0.80       # 16 TP berskor tinggi\ns_ties[20:204] = 0.80    # 184 FP berskor tinggi yang sama (tie!)\nprec_t, rec_t, _ = precision_recall_curve(y_ties, s_ties)\nap_exact = average_precision_score(y_ties, s_ties)\npr_trapz_bad = auc(rec_t, prec_t)\n\nprint(\"\\n=== 2. Audit Bias Optimis Trapezoidal PR-AUC pada Skor Terkuantisasi (Ties) ===\")\nprint(f\"average_precision_score (Step-Function Benar) : {ap_exact:.4f}\")\nprint(f\"auc(recall, precision)  (Trapezoidal Optimis) : {pr_trapz_bad:.4f}  <-- BIAS +{pr_trapz_bad - ap_exact:.4f}!\")\n\n# -----------------------------------------------------------------------------\n# Audit 3: Dummy Majority Classifier — Accuracy 99.9% Menipu vs MCC = 0.0000\n# -----------------------------------------------------------------------------\ny_rare = np.concatenate([np.ones(10, dtype=int), np.zeros(9990, dtype=int)])\ny_dummy = np.zeros_like(y_rare)\nprint(\"\\n=== 3. Audit Dummy Majority Classifier (Prevalensi 0.1%) ===\")\nprint(\n    f\"Accuracy={accuracy_score(y_rare, y_dummy):.4%} (MENIPU!) | \"\n    f\"F1={f1_score(y_rare, y_dummy, zero_division=0):.4f} | \"\n    f\"MCC={matthews_corrcoef(y_rare, y_dummy):.4f} (JUJUR!)\"\n)",
          "expectedOutput": "=== 1. Audit Sensitivitas Prevalensi (Kualitas Diskriminasi Model 100% Identik!) ===\nPrevalensi pi=0.20% | ROC-AUC=0.9330 (STABIL) | AP=0.0755 (BERUBAH 37.8x baseline!)\nPrevalensi pi=1.00% | ROC-AUC=0.9155 (STABIL) | AP=0.2725 (BERUBAH 27.2x baseline!)\nPrevalensi pi=5.00% | ROC-AUC=0.9256 (STABIL) | AP=0.5415 (BERUBAH 10.8x baseline!)\n\n=== 2. Audit Bias Optimis Trapezoidal PR-AUC pada Skor Terkuantisasi (Ties) ===\naverage_precision_score (Step-Function Benar) : 0.0660\nauc(recall, precision)  (Trapezoidal Optimis) : 0.4410  <-- BIAS +0.3750!\n\n=== 3. Audit Dummy Majority Classifier (Prevalensi 0.1%) ===\nAccuracy=99.9000% (MENIPU!) | F1=0.0000 | MCC=0.0000 (JUJUR!)",
