          "code": "import numpy as np\n\nrng = np.random.default_rng(282)\n\n# -----------------------------------------------------------------------------\n# First-Principles NumPy: Dekomposisi 3-Suku Murphy (1973) & Brier Skill Score\n# BS = Reliability (REL) - Resolution (RES) + Uncertainty (UNC)\n# -----------------------------------------------------------------------------\ndef murphy_brier_decomposition(y_true: np.ndarray, p_pred: np.ndarray, n_bins: int = 10) -> dict[str, float]:\n    y = np.asarray(y_true, dtype=float)\n    p = np.asarray(p_pred, dtype=float)\n    n = len(y)\n    # Kuantisasi probabilitas ke pusat bin diskrit agar setiap nilai p_k di bin B_k tepat seragam\n    edges = np.linspace(0.0, 1.0, n_bins + 1)\n    bin_ids = np.clip(np.digitize(p, edges[1:-1], right=False), 0, n_bins - 1)\n    p_binned = np.empty_like(p)\n    for b in range(n_bins):\n        mask = bin_ids == b\n        if np.any(mask):\n            p_binned[mask] = float(np.mean(p[mask]))\n\n    o_bar = float(np.mean(y))\n    unc = o_bar * (1.0 - o_bar)\n\n    rel = 0.0\n    res = 0.0\n    for b in range(n_bins):\n        mask = bin_ids == b\n        nk = int(np.sum(mask))\n        if nk == 0:\n            continue\n        pk = float(p_binned[mask][0])\n        ok = float(np.mean(y[mask]))\n        rel += (nk / n) * (pk - ok) ** 2\n        res += (nk / n) * (ok - o_bar) ** 2\n\n    bs_exact = float(np.mean((p_binned - y) ** 2))\n    bs_murphy = rel - res + unc\n    bss = 1.0 - bs_exact / unc if unc > 0 else 0.0\n    return {\n        \"bs\": bs_exact,\n        \"rel\": rel,\n        \"res\": res,\n        \"unc\": unc,\n        \"identity_err\": abs(bs_exact - bs_murphy),\n        \"bss\": bss,\n    }\n\n# Bangkitkan 4.000 observasi dengan probabilitas posterior sejati p_true\nz = rng.normal(loc=-0.9, scale=1.4, size=4000)\np_true = 1.0 / (1.0 + np.exp(-z))\ny_obs = (rng.uniform(size=4000) < p_true).astype(int)\n\n# 3 Model Kandidat:\n# (1) Terkalibrasi Tajam (mendekati posterior sejati)\np_calib = np.clip(p_true, 1e-4, 1.0 - 1e-4)\n# (2) Overconfident (suhu T=0.35 -> ranking 100% IDENTIK, tapi probabilitas ekstrem!)\np_over = 1.0 / (1.0 + np.exp(-z / 0.35))\n# (3) Klimatologi Konstan (selalu memprediksi prevalensi rata-rata)\np_const = np.full_like(p_true, y_obs.mean())\n\nprint(\"=== Dekomposisi 3-Suku Murphy (BS = REL - RES + UNC) & Brier Skill Score ===\")\nfor name, p_hat in [\n    (\"1. Model Terkalibrasi Tajam\", p_calib),\n    (\"2. Model Overconfident (T=0.35)\", p_over),\n    (\"3. Baseline Konstan (o_bar)\", p_const),\n]:\n    d = murphy_brier_decomposition(y_obs, p_hat, n_bins=10)\n    print(\n        f\"{name:31s} | BS={d['bs']:.5f} | REL={d['rel']:.5f} | RES={d['res']:.5f} | \"\n        f\"UNC={d['unc']:.5f} | BSS={d['bss']:+.4f} | |err|={d['identity_err']:.1e}\"\n    )",
