          "code": "import numpy as np\nfrom sklearn.calibration import CalibratedClassifierCV\nfrom sklearn.datasets import make_classification\nfrom sklearn.frozen import FrozenEstimator\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import brier_score_loss, log_loss, roc_auc_score\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.naive_bayes import GaussianNB\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\n\n# Dataset risiko klaim asuransi (N=2.400) dengan 14 fitur redundant berkorelasi tinggi\n# -> GaussianNB melanggar asumsi independensi secara ekstrem dan menjadi sangat overconfident!\nX, y = make_classification(\n    n_samples=2400,\n    n_features=20,\n    n_informative=4,\n    n_redundant=14,\n    weights=[0.78, 0.22],\n    class_sep=0.95,\n    random_state=282,\n)\nX_tr, X_tmp, y_tr, y_tmp = train_test_split(X, y, test_size=0.50, stratify=y, random_state=42)\nX_cal, X_te, y_cal, y_te = train_test_split(X_tmp, y_tmp, test_size=0.50, stratify=y_tmp, random_state=42)\n\nlogreg = make_pipeline(StandardScaler(), LogisticRegression(max_iter=500, random_state=42)).fit(X_tr, y_tr)\ngnb_raw = GaussianNB().fit(X_tr, y_tr)\n# Kalibrasi pasca-latih bebas leakage memakai FrozenEstimator di partisi X_cal!\ngnb_cal = CalibratedClassifierCV(FrozenEstimator(gnb_raw), method=\"sigmoid\").fit(X_cal, y_cal)\n\ndef rel_res_unc(y_true: np.ndarray, p_hat: np.ndarray, n_bins: int = 10) -> tuple[float, float, float]:\n    edges = np.linspace(0.0, 1.0, n_bins + 1)\n    bids = np.clip(np.digitize(p_hat, edges[1:-1]), 0, n_bins - 1)\n    o_bar = float(np.mean(y_true))\n    unc = o_bar * (1.0 - o_bar)\n    rel, res = 0.0, 0.0\n    for b in range(n_bins):\n        m = bids == b\n        if np.any(m):\n            w = float(np.mean(m))\n            pk = float(np.mean(p_hat[m]))\n            ok = float(np.mean(y_true[m]))\n            rel += w * (pk - ok) ** 2\n            res += w * (ok - o_bar) ** 2\n    return rel, res, unc\n\no_bar_te = float(y_te.mean())\nunc_te = o_bar_te * (1.0 - o_bar_te)\n\nprint(\"=== Evaluasi Strictly Proper Scoring Rules & Murphy Decomposition (Held-Out Test) ===\")\nfor name, clf in [\n    (\"LogisticRegression\", logreg),\n    (\"GaussianNB (Raw Overconf)\", gnb_raw),\n    (\"GaussianNB + Sigmoid Calib\", gnb_cal),\n]:\n    p = clf.predict_proba(X_te)[:, 1]\n    ll = log_loss(y_te, p)\n    bs = brier_score_loss(y_te, p)\n    bss = 1.0 - bs / unc_te\n    auc_v = roc_auc_score(y_te, p)\n    rel, res, _ = rel_res_unc(y_te, p, n_bins=10)\n    print(\n        f\"{name:26s} | ROC={auc_v:.4f} | LogLoss={ll:.4f} | BS={bs:.4f} | \"\n        f\"BSS={bss:+.4f} | REL={rel:.4f} | RES={res:.4f}\"\n    )",
          "expectedOutput": "=== Evaluasi Strictly Proper Scoring Rules & Murphy Decomposition (Held-Out Test) ===\nLogisticRegression         | ROC=0.7571 | LogLoss=0.4415 | BS=0.1364 | BSS=+0.2095 | REL=0.0039 | RES=0.0402\nGaussianNB (Raw Overconf)  | ROC=0.8215 | LogLoss=0.9731 | BS=0.1939 | BSS=-0.1241 | REL=0.0615 | RES=0.0377\nGaussianNB + Sigmoid Calib | ROC=0.8215 | LogLoss=0.4271 | BS=0.1346 | BSS=+0.2198 | REL=0.0010 | RES=0.0385",
          "actualOutput": "=== Evaluasi Strictly Proper Scoring Rules & Murphy Decomposition (Held-Out Test) ===\nLogisticRegression         | ROC=0.7571 | LogLoss=0.4415 | BS=0.1364 | BSS=+0.2095 | REL=0.0039 | RES=0.0402\nGaussianNB (Raw Overconf)  | ROC=0.8215 | LogLoss=0.9731 | BS=0.1939 | BSS=-0.1241 | REL=0.0615 | RES=0.0377\nGaussianNB + Sigmoid Calib | ROC=0.8215 | LogLoss=0.4271 | BS=0.1346 | BSS=+0.2198 | REL=0.0010 | RES=0.0385",
