          "id": "code-ml-28-3-ch28_3_diag",
          "title": "Production Audit: Model A Menang F1 (0.92 vs 0.75) Tapi Kalah Telak +$3.640 di Expected Value Bisnis!",
          "language": "python",
          "filename": "28_3_f1_winner_vs_profit_winner_audit.py",
          "code": "import numpy as np\nfrom sklearn.metrics import f1_score, roc_auc_score\n\nrng = np.random.default_rng(2833)\n\n# -----------------------------------------------------------------------------\n# Production Audit: Model A Menang F1 & ROC-AUC, tetapi Model B Menang Telak di Laba Bisnis!\n# -----------------------------------------------------------------------------\nn = 3000\n# 10% nasabah korporat bernilai besar ($1.200), 90% ritel bernilai kecil ($35)\nis_whale = rng.uniform(size=n) < 0.10\ntx_val = np.where(is_whale, rng.uniform(800.0, 1600.0, size=n), rng.uniform(20.0, 50.0, size=n))\ny_true = (rng.uniform(size=n) < 0.08).astype(int)\n\n# Model A: sangat akurat pada 90% transaksi ritel kecil, tapi hampir buta (acak) pada nasabah whale!\nscore_a = np.where(\n    ~is_whale,\n    np.clip(0.05 + 0.72 * y_true + rng.normal(0, 0.16, size=n), 0.01, 0.99),\n    np.clip(0.08 + 0.05 * y_true + rng.normal(0, 0.12, size=n), 0.01, 0.99),\n)\n# Model B: sedikit lebih berisik pada ritel kecil, namun sangat tajam menangkap fraud nasabah whale!\nscore_b = np.where(\n    is_whale,\n    np.clip(0.04 + 0.78 * y_true + rng.normal(0, 0.14, size=n), 0.01, 0.99),\n    np.clip(0.06 + 0.56 * y_true + rng.normal(0, 0.22, size=n), 0.01, 0.99),\n)\n\nc_review = 22.0\ndef expected_savings_metrics(y: np.ndarray, p: np.ndarray, v: np.ndarray) -> dict[str, float]:\n    roc = roc_auc_score(y, p)\n    f1_05 = f1_score(y, (p >= 0.50).astype(int))\n    # Keputusan berdasar F1 simetris (tau=0.50) vs aturan instance-dependent EV (p * v > c_review)\n    act_f1 = (p >= 0.50).astype(int)\n    act_ev = (p * v > c_review).astype(int)\n    # Laba bersih: TP menyelamatkan v_i - c_review; FP rugi -c_review\n    prof_f1 = float(np.sum(np.where(act_f1 == 1, y * v - c_review, 0.0)))\n    prof_ev = float(np.sum(np.where(act_ev == 1, y * v - c_review, 0.0)))\n    # Top-10% kapasitas diurutkan berdasarkan Expected Value (p * v)\n    k10 = int(0.10 * len(y))\n    top10 = np.argsort(-(p * v))[:k10]\n    prof_top10 = float(np.sum(y[top10] * v[top10] - c_review))\n    return {\"roc\": roc, \"f1_05\": f1_05, \"prof_f1\": prof_f1, \"prof_ev\": prof_ev, \"prof_top10\": prof_top10}\n\nres_a = expected_savings_metrics(y_true, score_a, tx_val)\nres_b = expected_savings_metrics(y_true, score_b, tx_val)\n\nprint(\"=== Audit Pemilihan Model: Metrik Simetris (ROC/F1) vs Expected Value Bisnis ===\")\nfor name, r in [(\"Model A (Jagoan Ritel Kecil)\", res_a), (\"Model B (Jagoan Nasabah Whale)\", res_b)]:\n    print(\n        f\"{name:30s} | ROC={r['roc']:.4f} | F1@0.5={r['f1_05']:.4f} | \"\n        f\"Profit(tau=0.5)=${r['prof_f1']:9,.2f} | Profit(EV)=${r['prof_ev']:9,.2f} | Top-10% EV=${r['prof_top10']:9,.2f}\"\n    )\nprint(f\"Keunggulan Bisnis Model B atas Model A (Aturan EV): +${res_b['prof_ev'] - res_a['prof_ev']:,.2f}!\")",
          "expectedOutput": "=== Audit Pemilihan Model: Metrik Simetris (ROC/F1) vs Expected Value Bisnis ===\nModel A (Jagoan Ritel Kecil)   | ROC=0.9718 | F1@0.5=0.9206 | Profit(tau=0.5)=$ 2,159.68 | Profit(EV)=$16,264.42 | Top-10% EV=$16,121.14\nModel B (Jagoan Nasabah Whale) | ROC=0.9672 | F1@0.5=0.7455 | Profit(tau=0.5)=$23,003.22 | Profit(EV)=$19,905.21 | Top-10% EV=$19,835.78\nKeunggulan Bisnis Model B atas Model A (Aturan EV): +$3,640.79!",
          "actualOutput": "=== Audit Pemilihan Model: Metrik Simetris (ROC/F1) vs Expected Value Bisnis ===\nModel A (Jagoan Ritel Kecil)   | ROC=0.9718 | F1@0.5=0.9206 | Profit(tau=0.5)=$ 2,159.68 | Profit(EV)=$16,264.42 | Top-10% EV=$16,121.14\nModel B (Jagoan Nasabah Whale) | ROC=0.9672 | F1@0.5=0.7455 | Profit(tau=0.5)=$23,003.22 | Profit(EV)=$19,905.21 | Top-10% EV=$19,835.78\nKeunggulan Bisnis Model B atas Model A (Aturan EV): +$3,640.79!",
          "explanation": "Membuktikan kegagalan pemilihan model berbasis metrik simetris pada campuran transaksi ritel ($35) dan korporat whale ($1.200): Model A unggul di ROC (0.9718) & F1 (0.9206), namun Model B unggul telak +$3.640,79 di aturan EV dan +$20.843,54 di ambang 0.5.",
